from pathlib import Path
import json,hashlib
from render_dialogue_script import render
r=Path(__file__).parent
# 현행 대사·독백을 보존하고 해당 장면의 행동으로 드러나는 의도와 갈등만 보충한다.
notes={
1:{1:'시인은 다시 쓰고 싶었지만, 이야기에 손을 대면 잊고 지내던 사람들까지 떠오를까 두려웠다. 반가운 기억에도 아픈 마음이 함께 따라왔다.'},
2:{3:'지배인은 시인의 능력을 칭찬하며 도움을 끌어내려 했다. 시인도 공연이 잘되기를 바랐지만, 인기를 얻는 일부터 생각하라는 말에는 쉽게 동의할 수 없었다.',17:'희극 배우는 두 사람 가운데 한쪽을 꺾으려 하지 않았다. 시인이 지키려는 작품의 힘을 관객도 즐길 수 있게 쓰자며, 함께 일할 방법을 찾고 있었다.'},
3:{9:'메피스토는 파우스트가 늘 더 큰 것을 원한다는 점을 이용하려 했다. 그 욕심을 계속 자극하면, 파우스트도 주가 기대하는 길에서 벗어나게 할 수 있다고 자신했다.',10:'주는 파우스트가 흔들릴 수 있다는 사실을 알고 있었다. 그래도 그가 애쓰는 동안에는 스스로 길을 찾아갈 가능성이 남아 있다고 보았다.'},
4:{18:'파우스트는 두려워하면서도 물러서면 지금까지의 공부와 노력이 모두 헛된 것 같았다. 자신도 정령과 같다는 말에는 그토록 바라던 만남에서 밀려나고 싶지 않은 마음이 담겼다.',23:'바그너는 배우고 싶은 마음으로 질문했지만, 파우스트는 방금 겪은 실패 때문에 말솜씨를 논할 여유가 없었다. 같은 대화를 하면서도 두 사람이 급하게 여기는 문제는 달랐다.',31:'바그너는 더 묻고 싶었지만 스승이 지쳤다는 것을 느꼈다. 파우스트 역시 바그너를 가르쳐야 한다는 것을 알면서도, 지금은 자기 혼란부터 추스를 시간이 필요했다.'},
5:{4:'친구와 함께 놀고 싶은 마음은 있었지만, 자신만 곁에서 구경하게 될까 봐 서운했다. 돌아가겠다는 말은 나들이가 싫어서라기보다, 함께 있어도 외로울 것 같아서였다.',38:'사람들의 감사는 파우스트를 기쁘게 하면서도 불편하게 했다. 남들이 기억하는 훌륭한 의사와, 자신의 치료를 의심하는 마음 사이에 차이가 있었기 때문이다.'},
6:{22:'메피스토는 이름을 바로 밝히는 대신 질문을 되돌려 파우스트를 떠봤다. 상대가 정체를 알아내려 할수록, 자신이 던진 수수께끼에 더 오래 매달리게 할 수 있었다.',28:'메피스토는 나갈 수 없다는 약점부터 드러내고 싶지 않았다. 평범한 방문객처럼 허락을 구하면 파우스트가 대수롭지 않게 보내 줄 수도 있다고 여겼다.',35:'파우스트는 악마를 붙잡았다는 사실에 자신감을 얻었다. 메피스토는 그가 쉽게 놓아주지 않으리라는 것을 알고, 힘으로 버티기보다 관심을 다른 곳으로 돌릴 방법을 찾았다.',36:'즐거운 구경을 보여 주겠다는 제안은 파우스트를 위한 호의처럼 들렸다. 그러나 메피스토가 바라는 것은 파우스트가 경계를 풀고 자신을 붙잡아 두려던 일까지 잊는 것이었다.'},
7:{13:'메피스토는 도움부터 약속해 혼자 괴로워하던 파우스트가 자신에게 기대게 하려 했다. 파우스트도 그 도움이 솔깃했지만, 악마가 무엇을 받아 갈지 몰라 대가부터 확인했다.',18:'파우스트는 즐거움 몇 가지로 자신을 멈추게 할 수 없다고 믿었다. 메피스토는 그 자신만만함이 오히려 내기를 받아들이게 만든다는 것을 보고 기꺼이 응했다.',24:'메피스토는 파우스트의 긴 항의를 짧은 요구 하나로 끝냈다. 복잡하게 따질 일도 아니라는 듯 말하면, 파우스트도 서명을 대수롭지 않게 넘길 수 있었다.',39:'학생은 이름 높은 학자에게 길을 묻는다고 믿어 긴장을 풀었다. 메피스토는 그 믿음을 바로잡지 않았다. 상대가 자기 말을 의심하지 않을수록 마음대로 이끌기 쉬웠다.',52:'학생은 이해하지 못하는 말을 외우기만 해도 되는지 의문이 들었다. 하지만 상대가 자신보다 훨씬 많이 안다고 믿었기에, 질문하고도 끝까지 반박하기는 어려웠다.'},
8:{42:'메피스토는 술을 줄 수 있는지 설명하는 대신, 무엇을 마시고 싶은지 계속 물었다. 술꾼들이 각자 원하는 술을 고르다 보면 의심보다 기대가 먼저 커질 수 있었다.',46:'파우스트가 지루해하자 메피스토는 조금만 더 보라고 붙잡았다. 평범한 술자리보다 사람들의 욕심과 당황하는 모습을 보여 주는 일이 그에게는 더 재미있었다.'},
9:{6:'메피스토는 다른 방법도 있다는 말로 선택권을 주는 척했다. 파우스트가 고된 생활을 거절하면, 결국 마녀의 약을 택하도록 이끌 수 있었다.',18:'파우스트가 거울에서 눈을 떼지 못하자 메피스토는 더 설득할 필요가 줄었다고 느꼈다. 젊어지고 싶은 마음에 아름다운 사람을 만나고 싶은 마음까지 더해지고 있었다.',45:'메피스토는 거울을 다시 보게 하는 대신 실제로 만날 사람을 약속했다. 눈앞의 환상에 머무르려는 파우스트를 밖으로 움직이게 하려는 말이었다.'},
10:{4:'메피스토는 당장 뜻대로 할 수 없다는 것을 알리면서도, 파우스트의 관심이 식는 것은 원하지 않았다. 어려운 일이라고 말할수록 오히려 파우스트가 더 고집을 부릴 수도 있었다.',9:'방을 보게 해 주겠다는 약속은 그레첸을 만나게 해 달라는 요구와 달랐다. 그래도 파우스트는 그녀에게 조금이라도 가까워질 수 있다는 생각에 그 제안을 놓치고 싶지 않았다.'},
11:{2:'파우스트는 그레첸을 다시 만나고 싶어 따라왔지만, 막상 그녀의 생활이 담긴 방에 들어서니 함부로 굴기 어려웠다. 메피스토는 그런 변화를 지켜보면서도 가벼운 말투를 거두지 않았다.',11:'메피스토는 서둘러 나가려던 파우스트를 선물로 붙잡았다. 상자를 두고 가게 하면, 그레첸을 향한 관심도 여기서 끝나지 않을 터였다.',12:'메피스토는 파우스트의 걱정이 어디서 시작됐는지 묻지 않았다. 보석이 아까운 거냐고 놀려 버리면, 파우스트가 자기 망설임을 차분히 설명하기 어려워졌다.',13:'상자를 두고 가는 일을 마쳐 버리면 파우스트가 다시 고민할 틈도 줄었다. 메피스토는 그의 대답을 기다리기보다 먼저 손을 움직였다.',19:'그레첸은 남의 물건일 수 있다는 것을 알면서도 자기에게 어울릴지 궁금했다. 주인을 확인해야 한다는 생각과 잠깐만 해 보고 싶은 마음이 함께 들었다.'},
12:{7:'파우스트는 그레첸이 속상하다는 말에 마음이 쓰였다. 하지만 그녀와 직접 이야기할 수는 없었기에, 다시 선물을 주는 일이 당장 할 수 있는 해결책처럼 느껴졌다.',8:'메피스토는 일이 늘어나는 게 못마땅했지만, 파우스트가 계속 자기를 찾는 상황은 나쁘지 않았다. 선물을 구하고 만날 길을 여는 일을 자신에게 맡길수록 파우스트는 그에게 더 의지하게 됐다.'},
13:{8:'메피스토는 그레첸이 경계하기보다 칭찬을 받아들이게 하려 했다. 보석뿐 아니라 몸가짐까지 칭찬하면, 처음 만난 자신을 호의적인 손님으로 여기기 쉬웠다.',20:'메피스토는 마르테가 용서했다는 말을 하자마자 남편이 아내를 탓했다는 이야기를 꺼냈다. 마르테는 슬퍼할 틈도 없이 해명하고 따지게 됐고, 대화는 다시 그가 내놓는 이야기대로 흘렀다.',23:'마르테는 남편을 잃은 슬픔 속에서도 자신과 아이들의 살림을 걱정했다. 메피스토는 보물이 어디 있느냐는 질문에 답하지 않고 다른 여자 이야기를 꺼내, 그녀의 관심을 분노 쪽으로 돌렸다.',26:'마르테는 남편을 원망하면서도 다정했던 모습까지 지울 수는 없었다. 메피스토의 결혼 농담은 그 복잡한 마음에 새로운 기대를 끼워 넣는 말이었다.',30:'메피스토가 데려오려는 동료는 파우스트였다. 남편의 죽음을 확인하고 싶은 마르테의 필요를 이용하면, 파우스트와 그레첸이 만날 이유도 자연스럽게 마련할 수 있었다.'},
14:{5:'파우스트는 그레첸을 만나고 싶었지만, 확인하지도 않은 죽음을 사실이라고 말하는 데는 거부감이 들었다. 메피스토는 그 망설임을 존중하기보다 유난히 까다롭게 구는 일처럼 취급했다.',7:'학문 이야기에 파우스트가 화를 내자 메피스토는 사랑 이야기로 옮겨 갔다. 그레첸에게 할 말까지 거짓말과 나란히 놓으면, 파우스트가 증언만 따로 떼어 거절하기 어려워질 거라 본 것이다.',10:'파우스트는 거짓 증언이 옳다는 데 동의한 것이 아니었다. 다만 메피스토와 등을 돌리면 그레첸을 만날 기회도 놓칠까 봐, 자기 불편한 마음을 끝까지 밀고 나가지 못했다.'},
15:{4:'마르테는 그가 계속 떠도는 사람인지, 누군가와 함께 살 생각도 있는지 알고 싶었다. 메피스토는 그런 뜻을 알아들었지만, 진지한 대답을 하기보다 걱정에 맞장구치며 넘겼다.',8:'그레첸에게 동생을 돌본 시간은 힘들었다고만 말할 수 없는 기억이었다. 잠 못 자던 고생도 선명했지만, 그 수고를 다시 할 수 있다면 동생을 다시 만날 수 있다는 뜻이었기 때문이다.',13:'메피스토는 질문을 못 알아들은 것이 아니었다. 대답을 피하면서도 칭찬을 해 주면, 마르테를 정면으로 거절하지 않은 채 대화를 이어 갈 수 있었다.',18:'그레첸은 파우스트의 마음을 알고 싶었지만, 직접 물었다가 혼자 앞서갔다는 답을 들을까 두려웠다. 꽃잎 놀이로 묻는 편이 덜 부끄러웠다.'},
16:{3:'파우스트에게는 방해가 반갑지 않았지만, 마르테는 늦은 시간까지 붙잡아 둘 수 없었다. 메피스토는 아쉬워하는 파우스트와 달리 작별을 재촉했다. 두 사람의 시간은 자신이 끼어들면 끝낼 수 있었다.',4:'그레첸도 더 함께 있고 싶었다. 그렇지만 집에서 어머니를 마주할 일을 생각하니, 지금의 기쁨만 따라 배웅을 받아들일 수는 없었다.'},
17:{9:'메피스토는 파우스트가 숲에서 얻은 평온을 소중한 경험으로 인정해 주지 않았다. 그것도 우스운 일로 만들어 버리면, 여기 남아 있으려는 마음을 약하게 할 수 있었다.',11:'메피스토는 그레첸이 기다린다는 말에 책임감까지 얹었다. 파우스트가 돌아가고 싶어 하면서도 머무르려 한다면, 그녀를 혼자 괴롭게 두는 셈이라고 느끼게 하려는 것이었다.',14:'파우스트는 메피스토의 의도를 알아차렸지만 그레첸을 걱정하는 마음까지 없앨 수는 없었다. 듣지 말아야겠다는 생각과 더 알고 싶다는 마음이 부딪쳤다.',19:'파우스트는 메피스토가 자신을 몰아간다고 비난하면서도, 이 불안을 끝내 줄 도움은 다시 그에게 청했다. 의심하는 상대에게 기대야 한다는 사실이 마음을 더 복잡하게 만들었다.',21:'메피스토는 파우스트의 걱정을 웃어넘기며 찾아가기만 하면 된다고 밀어붙였다. 파우스트가 멈춰서 두 사람의 앞날을 생각할수록, 자신이 원하는 쪽으로 움직이게 하기 어려워졌기 때문이다.'}}
audit=[]
for ch,items in notes.items():
 p=r/f'adaptations/chapter-{ch:02}.json';d=json.loads(p.read_text(encoding='utf-8'));before=json.dumps(d.get('monologues') if ch==1 else [b.get('monologue') for b in d['scenes']],ensure_ascii=False)
 for no,text in items.items():
  flow=d['scripts'][no-1] if ch==1 else d['scenes'][no-1]['script']
  if any(x.get('editorial_tag')=='friendly-motivation-2026-11-18' for x in flow):continue
  node=dict(role='narration',speaker='나레이터',cast_id='narrator',text=text,editorial_tag='friendly-motivation-2026-11-18')
  pos=next((i for i,x in enumerate(flow) if x['role']=='monologue'),len(flow));flow.insert(pos,node)
  if ch==1:d['passages'][no-1]='\n'.join(x['text'] for x in flow if x['role']!='monologue')
  else:d['scenes'][no-1]['narration']='\n'.join('“'+x['text']+'”' if x['role']=='dialogue' else x['text'] for x in flow if x['role']!='monologue')
  audit.append(dict(chapter=ch,scene=no,added=text))
 after=json.dumps(d.get('monologues') if ch==1 else [b.get('monologue') for b in d['scenes']],ensure_ascii=False);assert before==after
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8');render(ch)
(r/'friendly-motivation-audit.json').write_text(json.dumps(dict(additions=audit,monologues_preserved=True,dialogue_preserved=True),ensure_ascii=False,indent=2),encoding='utf-8')
print('Added friendly narration:',len(audit),'passages;existing monologues and dialogue preserved')
